CREATE VIEW "EXT"."VW_COMPARAR_ST_DEBUG"("LINE") AS
( 		(SELECT "LINE"
		FROM 
			(
				(SELECT 'ORDERID;LINENUMBER;CLAVE3;BATCHNAME;ACCOUNTINGDATE;PRODUCTID;PRODUCTNAME;PRODUCTDESCRIPTION;VALUE;UNITTYPEFORVALUE;NUMBEROFUNITS;UNITVALUE;UNITTYPEFORUNITVALUE;COMPENSATIONDATE;PAYMENTTERMS;NATIVECURRENCY;NATIVECURRENCYAMOUNT;DISCOUNTPERCENT;DISCOUNTTYPE;GENERICATTRIBUTE1;GENERICATTRIBUTE2;GENERICATTRIBUTE3;GENERICATTRIBUTE4;GENERICATTRIBUTE5;GENERICATTRIBUTE6;GENERICATTRIBUTE7;GENERICATTRIBUTE8;GENERICATTRIBUTE9;GENERICATTRIBUTE10;GENERICATTRIBUTE11;GENERICATTRIBUTE12;GENERICATTRIBUTE13;GENERICATTRIBUTE14;GENERICATTRIBUTE15;GENERICATTRIBUTE16;GENERICATTRIBUTE17;GENERICATTRIBUTE18;GENERICATTRIBUTE19;GENERICATTRIBUTE20;GENERICATTRIBUTE21;GENERICATTRIBUTE22;GENERICATTRIBUTE23;GENERICATTRIBUTE24;GENERICATTRIBUTE25;GENERICATTRIBUTE26;GENERICATTRIBUTE27;GENERICATTRIBUTE28;GENERICATTRIBUTE29;GENERICATTRIBUTE30;GENERICATTRIBUTE31;GENERICATTRIBUTE32;GENERICNUMBER1;UNITTYPEFORGENERICNUMBER1;GENERICNUMBER2;UNITTYPEFORGENERICNUMBER2;GENERICNUMBER3;UNITTYPEFORGENERICNUMBER3;GENERICNUMBER4;UNITTYPEFORGENERICNUMBER4;GENERICNUMBER5;UNITTYPEFORGENERICNUMBER5;GENERICNUMBER6;UNITTYPEFORGENERICNUMBER6;GENERICDATE1;GENERICDATE2;GENERICDATE3;GENERICDATE4;GENERICDATE5;GENERICDATE6;GENERICBOOLEAN1;GENERICBOOLEAN2;GENERICBOOLEAN3;GENERICBOOLEAN4;GENERICBOOLEAN5;GENERICBOOLEAN6' AS LINE
				FROM DUMMY

				UNION ALL

				SELECT LINE AS LINE
				FROM EXT.COMPARAR_ST_DEBUG)
			)
		ORDER BY 
			CASE
				WHEN LINE = 'ORDERID;LINENUMBER;CLAVE3;BATCHNAME;ACCOUNTINGDATE;PRODUCTID;PRODUCTNAME;PRODUCTDESCRIPTION;VALUE;UNITTYPEFORVALUE;NUMBEROFUNITS;UNITVALUE;UNITTYPEFORUNITVALUE;COMPENSATIONDATE;PAYMENTTERMS;NATIVECURRENCY;NATIVECURRENCYAMOUNT;DISCOUNTPERCENT;DISCOUNTTYPE;GENERICATTRIBUTE1;GENERICATTRIBUTE2;GENERICATTRIBUTE3;GENERICATTRIBUTE4;GENERICATTRIBUTE5;GENERICATTRIBUTE6;GENERICATTRIBUTE7;GENERICATTRIBUTE8;GENERICATTRIBUTE9;GENERICATTRIBUTE10;GENERICATTRIBUTE11;GENERICATTRIBUTE12;GENERICATTRIBUTE13;GENERICATTRIBUTE14;GENERICATTRIBUTE15;GENERICATTRIBUTE16;GENERICATTRIBUTE17;GENERICATTRIBUTE18;GENERICATTRIBUTE19;GENERICATTRIBUTE20;GENERICATTRIBUTE21;GENERICATTRIBUTE22;GENERICATTRIBUTE23;GENERICATTRIBUTE24;GENERICATTRIBUTE25;GENERICATTRIBUTE26;GENERICATTRIBUTE27;GENERICATTRIBUTE28;GENERICATTRIBUTE29;GENERICATTRIBUTE30;GENERICATTRIBUTE31;GENERICATTRIBUTE32;GENERICNUMBER1;UNITTYPEFORGENERICNUMBER1;GENERICNUMBER2;UNITTYPEFORGENERICNUMBER2;GENERICNUMBER3;UNITTYPEFORGENERICNUMBER3;GENERICNUMBER4;UNITTYPEFORGENERICNUMBER4;GENERICNUMBER5;UNITTYPEFORGENERICNUMBER5;GENERICNUMBER6;UNITTYPEFORGENERICNUMBER6;GENERICDATE1;GENERICDATE2;GENERICDATE3;GENERICDATE4;GENERICDATE5;GENERICDATE6;GENERICBOOLEAN1;GENERICBOOLEAN2;GENERICBOOLEAN3;GENERICBOOLEAN4;GENERICBOOLEAN5;GENERICBOOLEAN6' THEN 0
				ELSE 1
			END ASC, 
			LINE ASC) )
WITH READ ONLY;
